package com.ganga.zerogprace.stats;

import com.ganga.zerogprace.model.RaceSource;
import com.ganga.zerogprace.model.RaceTransaction;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

public final class RaceStatistics
{
    private final long score;
    private final long positiveGp;
    private final long importedGp;
    private final int acceptedTransactions;
    private final String biggestItem;
    private final long biggestValue;
    private final Map<RaceSource, Long> gpBySource;

    private RaceStatistics(long score, long positiveGp, long importedGp, int acceptedTransactions,
                           String biggestItem, long biggestValue, Map<RaceSource, Long> gpBySource)
    {
        this.score = score;
        this.positiveGp = positiveGp;
        this.importedGp = importedGp;
        this.acceptedTransactions = acceptedTransactions;
        this.biggestItem = biggestItem;
        this.biggestValue = biggestValue;
        this.gpBySource = gpBySource;
    }

    public static RaceStatistics from(List<RaceTransaction> transactions, long score)
    {
        long positive = 0L;
        long imported = 0L;
        int accepted = 0;
        long biggest = 0L;
        String biggestItem = "None";
        Map<RaceSource, Long> bySource = new EnumMap<>(RaceSource.class);

        for (RaceTransaction transaction : transactions)
        {
            long delta = transaction.getScoreDelta();
            bySource.merge(transaction.getSource(), delta, Long::sum);
            if (delta > 0L)
            {
                positive += delta;
                accepted++;
                if (delta > biggest && !transaction.getItemName().isEmpty())
                {
                    biggest = delta;
                    biggestItem = transaction.getItemName();
                }
            }
            else if (delta < 0L)
            {
                imported += -delta;
            }
        }

        return new RaceStatistics(score, positive, imported, accepted, biggestItem, biggest, bySource);
    }

    public long getScore() { return score; }
    public long getPositiveGp() { return positiveGp; }
    public long getImportedGp() { return importedGp; }
    public int getAcceptedTransactions() { return acceptedTransactions; }
    public String getBiggestItem() { return biggestItem; }
    public long getBiggestValue() { return biggestValue; }
    public Map<RaceSource, Long> getGpBySource() { return gpBySource; }
}

package com.ganga.zerogprace.wallet;

import java.util.HashMap;
import java.util.Map;

final class InventoryBasisLedger
{
    private final Map<Integer, Integer> quantities = new HashMap<>();
    private final Map<Integer, Long> values = new HashMap<>();

    void add(int itemId, int quantity, long valueGp)
    {
        if (itemId <= 0 || quantity <= 0 || valueGp <= 0L)
        {
            return;
        }

        quantities.merge(itemId, quantity, Integer::sum);
        values.merge(itemId, valueGp, Long::sum);
    }

    long consume(int itemId, int quantity)
    {
        if (itemId <= 0 || quantity <= 0)
        {
            return 0L;
        }

        int heldQty = quantities.getOrDefault(itemId, 0);
        long heldValue = values.getOrDefault(itemId, 0L);

        if (heldQty <= 0 || heldValue <= 0L)
        {
            return 0L;
        }

        int usedQty = Math.min(quantity, heldQty);
        long usedValue;

        if (usedQty >= heldQty)
        {
            usedValue = heldValue;
            quantities.remove(itemId);
            values.remove(itemId);
        }
        else
        {
            usedValue = (heldValue * usedQty) / heldQty;
            int remainingQty = heldQty - usedQty;
            long remainingValue = Math.max(0L, heldValue - usedValue);

            quantities.put(itemId, remainingQty);
            values.put(itemId, remainingValue);
        }

        return Math.max(0L, usedValue);
    }

    void clear()
    {
        quantities.clear();
        values.clear();
    }
}

package com.ganga.zerogprace.network;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Objects;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public final class MultiplayerClient
{
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    public interface ResultCallback
    {
        void onSuccess(RaceRoomSnapshot room);
        void onError(String message);
    }

    private final OkHttpClient httpClient;
    private final Gson gson;
    private volatile NetworkStatus status = NetworkStatus.READY;

    public MultiplayerClient(OkHttpClient httpClient, Gson gson)
    {
        this.httpClient = Objects.requireNonNull(httpClient);
        this.gson = Objects.requireNonNull(gson);
    }

    public NetworkStatus getStatus()
    {
        return status;
    }

    public void reset()
    {
        status = NetworkStatus.READY;
    }

    public void createRoom(String apiBase, CreateRoomRequest payload, ResultCallback callback)
    {
        post(apiBase + "/api/create", payload, callback);
    }

    public void joinRoom(String apiBase, JoinRoomRequest payload, ResultCallback callback)
    {
        post(apiBase + "/api/join", payload, callback);
    }

    public void sync(String apiBase, RaceSyncPayload payload, ResultCallback callback)
    {
        post(apiBase + "/api/sync", payload, callback);
    }

    public void leave(String apiBase, LeaveRoomRequest payload, ResultCallback callback)
    {
        post(apiBase + "/api/leave", payload, callback);
    }

    public void fetchRoom(String apiBase, String roomCode, ResultCallback callback)
    {
        status = NetworkStatus.CONNECTING;
        Request request = new Request.Builder()
            .url(apiBase + "/api/room?roomCode=" + urlEncode(roomCode))
            .get()
            .build();
        execute(request, callback);
    }

    private void post(String url, Object payload, ResultCallback callback)
    {
        status = NetworkStatus.CONNECTING;
        Request request = new Request.Builder()
            .url(url)
            .post(RequestBody.create(JSON, gson.toJson(payload)))
            .build();
        execute(request, callback);
    }

    private void execute(Request request, ResultCallback callback)
    {
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException exception)
            {
                status = NetworkStatus.ERROR;
                callback.onError(exception.getMessage() == null ? "Connection failed" : exception.getMessage());
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response closable = response)
                {
                    String body = closable.body() == null ? "" : closable.body().string();
                    ApiResponse apiResponse;
                    try
                    {
                        apiResponse = gson.fromJson(body, ApiResponse.class);
                    }
                    catch (Exception ex)
                    {
                        status = NetworkStatus.ERROR;
                        callback.onError("Invalid server response");
                        return;
                    }

                    if (!closable.isSuccessful() || apiResponse == null || !apiResponse.isOk())
                    {
                        status = NetworkStatus.ERROR;
                        String message = apiResponse == null ? "Server error " + closable.code() : apiResponse.getMessage();
                        callback.onError(message.isEmpty() ? "Server error " + closable.code() : message);
                        return;
                    }

                    status = NetworkStatus.CONNECTED;
                    callback.onSuccess(apiResponse.getRoom());
                }
            }
        });
    }

    private static String urlEncode(String value)
    {
        try
        {
            return java.net.URLEncoder.encode(value == null ? "" : value, "UTF-8");
        }
        catch (java.io.UnsupportedEncodingException impossible)
        {
            return value == null ? "" : value;
        }
    }
}

